import re
from datetime import datetime


class NoRtpmIntervalCollected(Exception):
    def __init__(self, msg_name):
        super(NoRtpmIntervalCollected, self).__init__()
        self.msg_name = msg_name

    def __str__(self):
        return self.msg_name


class RTPMConverter(object):

    @classmethod
    def counter_id_int(cls, counter_id):
        srch = re.search(r'M(\d+)C(\d+)', counter_id)
        if srch:
            counter_id = 'M' + str(int(srch.group(1))) + 'C' + str(int(srch.group(2)))
        return counter_id

    def __init__(self, parse_rtpm_file_command_output, skip_not_valid_counters=0, rtpm_data=None,
                 interval_timestamps=None):
        self.raw_output = parse_rtpm_file_command_output
        self._skip_not_valid_counters = skip_not_valid_counters
        self.rtpm_data = self.convert_rtpm_data(rtpm_data)
        self.interval_timestamps = interval_timestamps
        self.converted_table = self.convert_parse_rtpm_file_output(self.raw_output)

    def convert_rtpm_data(self, rtpm_data):
        ret = {}
        if rtpm_data is None:
            return ret

        if not isinstance(rtpm_data, list):
            return ret

        for dn_entry in rtpm_data:
            if 'dn' in dn_entry and 'dn_meas' in dn_entry:
                dn = dn_entry['dn']
                meas_entry = dn_entry['dn_meas']
                for meas_id in meas_entry:
                    if 'COUNTERS' in meas_entry[meas_id]:
                        counters_entry = meas_entry[meas_id]['COUNTERS']
                        for counter_id in counters_entry:
                            if dn not in ret:
                                ret[dn] = {}
                            if counter_id not in ret[dn]:
                                ret[dn][counter_id] = {}
                            ret[dn][counter_id] = counters_entry[counter_id]
                            try:
                                val = self._convert_counter_value(ret[dn][counter_id]['VALUE'])
                                ret[dn][counter_id]['VALUE'] = val
                            except Exception:
                                pass
        return ret

    def _convert_counter_value(self, val):
        try:
            if re.search(r'\.', val):
                val = float(val)
            else:
                val = int(val)
        except Exception:
            pass
        return val

    def get_converted_table(self):
        return self.converted_table

    def get_counter_value(self, object, id):
        return self.get_counter_object_with_id(object, id)['VALUE']

    def get_all_counter_values(self, counter_id):
        return self.get_all_rtpm_data_values(counter_id)

    def get_counter_update_time(self, object, id):
        return None
        # TO DO return self.get_counter_object_with_id(object, id)['LATEST_UPDATE']

    def get_rtpm_data_value(self, object, id):
        id = self.counter_id_int(id)
        for obj in self.rtpm_data:
            if self.is_requested_dn(obj, object):
                if id in self.rtpm_data[obj]:
                    print("Found aggregated value={0} of requested object {1} in {2}".format(
                        self.rtpm_data[obj][id], object, obj))
                    return self.rtpm_data[obj][id]
        return None

    def get_all_rtpm_data_values(self, counter_id):
        counter_id = self.counter_id_int(counter_id)
        ret = {}
        for obj in self.rtpm_data:
            if counter_id in self.rtpm_data[obj]:
                print("Found aggregated value={} in {}".format(self.rtpm_data[obj][counter_id], obj))
                ret[obj] = self.rtpm_data[obj][counter_id]['VALUE']
        return ret

    def is_requested_dn(self, dn, object):
        patt = "(%s$|%s/)" % (object, object)
        if re.search(patt, dn):
            return True
        return False

    def get_counter_object_with_id(self, object, id):
        id = self.counter_id_int(id)
        val = self.get_rtpm_data_value(object, id)
        if val is not None:
            if self.interval_timestamps is None:
                print("Using aggregated value computed by emssim: {}".format(val))
                return val
            else:
                print("NOT using aggregated value: {}, because interval timestamps are used".format(val))
                pass

        found_counters = []
        for counter in self.converted_table:
            if object in counter['OBJECT'] and counter['COUNTER'] == id:
                # |*** Object: /HOME_CELL_LTE-244-09-1-12/LNCEL-2
                # |*** Object: /HOME_CELL_LTE-244-09-1-12/LNCEL-2/PLMN-244-09
                # |*** Object: /HOME_CELL_LTE-244-09-1-12/LNCEL-2/TARGET_EARFCN-1600
                # |*** Object: /HOME_CELL_LTE-244-09-1-12/LNCEL-268/PLMN-244-09
                print("RTPM object requested=%s, current object=%s" % (object, counter['OBJECT']))
                if self.is_requested_dn(counter['OBJECT'], object):
                    print("Found the RTPM counter in object=%s" % (counter['OBJECT']))
                    found_counters.append(counter)
        assert not len(found_counters) > 1, "More than one counter with id: %s of objects: %s found" % (id, object)
        assert not len(found_counters) == 0, "No counters with id: %s of objects: %s found" % (id, object)
        return found_counters[0]

    def convert_parse_rtpm_file_output(self, parse_rtpm_file_command_output):
        rtpm_table = []
        for measurement in parse_rtpm_file_command_output:
            rtpm_table.extend(self.convert_measurement(measurement))
        return rtpm_table

    def convert_measurement(self, measurement):
        measurement_table = []
        legend = self.convert_legend(measurement)
        for counter in measurement['table']:
            counter_dict = self.convert_counter(counter)
            counter_dict['VALUE'] = self.sum_counter_values(counter, legend)
            counter_dict['OBJECT'] = measurement['object']
            measurement_table.append(counter_dict)
        return measurement_table

    def convert_legend(self, measurement):
        """

        :param measurement:
        :return:
             {1: datetime_object}, where is is the number of interval
        """
        legend = {}
        if self.interval_timestamps is None:
            return None
        else:
            for interval in measurement['legend']:
                # matching T1  => 2019-05-09 14:26:00  to  (T1,2019,05,09,14,26,00)
                res = re.search(r'^T(\d+)\s*=>\s*(?:(\d{4})-(\d{2})-(\d{2}))*\s(?:(\d+):(\d+):(\d+))', interval)
                if res:
                    legend[int(res.group(1))] = datetime(int(res.group(2)), int(res.group(3)), int(res.group(4)),
                                                         int(res.group(5)), int(res.group(6)), int(res.group(7)))
            if len(legend) > 0:
                return legend
            else:
                return None

    def are_timestamps_in_same_interval(self):
        """
        Timestamps are of datetime.datetime type, e.g.datetime.datetime.now(), and have attrs as .hour, .minute

        :return:
        """
        if self.interval_timestamps is not None:
            (start, stop) = self.interval_timestamps
            if int((stop - start).total_seconds()) < 60 and start.minute == stop.minute:
                print('Start and stop timepoints are within the same 1-minute interval')
                return True
            else:
                print('Start and stop timepoints are in different 1-minute intervals')
                return False
        return None

    def find_t_intervals_matching_timestamps(self, legend):
        (start, stop) = self.interval_timestamps
        if self.are_timestamps_in_same_interval():
            for (t_value, t_data) in legend.items():
                if int((start - t_data).total_seconds()) in range(0, 60):
                    return [t_value]
        else:
            start_t, stop_t = None, None
            for (t_value, t_data) in legend.items():
                if int((start - t_data).total_seconds()) in range(0, 60):
                    start_t = t_value
                if int((stop - t_data).total_seconds()) in range(0, 60):
                    stop_t = t_value
                if start_t is not None and stop_t is not None:
                    return range(start_t, stop_t + 1)
        return []

    def sum_counter_values(self, counter, legend):
        counter_value = 0
        if legend is not None:
            matching_t_intervals = self.find_t_intervals_matching_timestamps(legend)
            if len(matching_t_intervals) == 0:
                raise NoRtpmIntervalCollected('Available timestamps: {}'.format(legend.values))
            print('Test intervals : {}-{} are matching following T_intervals in RTPM data: {}'
                  .format(self.interval_timestamps[0].ctime(), self.interval_timestamps[1].ctime(),
                          ["T{}={}".format(t_int, legend[t_int].ctime()) for t_int in matching_t_intervals]))
        for key in counter:
            res = re.search(r'^T(\d+)', key)
            if res:
                val = counter[key]
                if legend is None:
                    pass
                elif legend is not None and int(res.group(1)) in matching_t_intervals:
                    print('Interval T{} matched with counter value: {}'.format(int(res.group(1)), val))
                    pass
                else:
                    print('Filtering out interval: T{}, not matching requested intervals: {}'
                          .format(int(res.group(1)), ["T{}".format(t_in) for t_in in matching_t_intervals]))
                    continue
                if self._skip_not_valid_counters:
                    try:
                        counter_value += int(val)
                    except Exception:
                        pass
                else:
                    if val == '-':
                        assert False, "Empty RTPM value: interval=%s, counter=%s" % (key, counter['COUNTER'])
                    counter_value += int(val)

        if legend is not None:
            if counter['TYPE'] is not None and str(counter['TYPE']).lower() == 'average':
                counter_value = int(float(counter_value) / len(matching_t_intervals))
        return counter_value

    def convert_counter(self, counter):
        counter_dict = {
            'NAME': counter['NAME'],
            'COUNTER': counter['COUNTER'],
            'TYPE': counter['TYPE'] if 'TYPE' in counter else None
        }
        return counter_dict
